package org.apache.commons.jxpath.ri.parser;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.fail;

import java.io.StringReader;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;

import org.apache.commons.jxpath.ri.Compiler;
import org.junit.Test;

public class WildcardNameTests {

    private static final Object QNAME_RESULT = new Object();

    @Test
    public void parsesUnqualifiedName() throws Exception {
        RecordingCompiler compiler = new RecordingCompiler();
        Object result = parse("name", compiler);

        assertSame(QNAME_RESULT, result);
        assertEquals(1, compiler.callCount);
        assertEquals(null, compiler.namespace);
        assertEquals("name", compiler.localName);
    }

    @Test
    public void parsesWildcardName() throws Exception {
        RecordingCompiler compiler = new RecordingCompiler();
        Object result = parse("*", compiler);

        assertSame(QNAME_RESULT, result);
        assertEquals(1, compiler.callCount);
        assertEquals(null, compiler.namespace);
        assertEquals("*", compiler.localName);
    }

    @Test
    public void parsesQualifiedName() throws Exception {
        RecordingCompiler compiler = new RecordingCompiler();
        Object result = parse("prefix:name", compiler);

        assertSame(QNAME_RESULT, result);
        assertEquals(1, compiler.callCount);
        assertEquals("prefix", compiler.namespace);
        assertEquals("name", compiler.localName);
    }

    @Test
    public void parsesQualifiedWildcardName() throws Exception {
        RecordingCompiler compiler = new RecordingCompiler();
        Object result = parse("prefix:*", compiler);

        assertSame(QNAME_RESULT, result);
        assertEquals(1, compiler.callCount);
        assertEquals("prefix", compiler.namespace);
        assertEquals("*", compiler.localName);
    }

    @Test
    public void parsesWildcardNamespaceName() throws Exception {
        RecordingCompiler compiler = new RecordingCompiler();
        Object result = parse("*:name", compiler);

        assertSame(QNAME_RESULT, result);
        assertEquals(1, compiler.callCount);
        assertEquals("*", compiler.namespace);
        assertEquals("name", compiler.localName);
    }

    @Test
    public void parsesWildcardNamespaceAndLocalName() throws Exception {
        RecordingCompiler compiler = new RecordingCompiler();
        Object result = parse("*:*", compiler);

        assertSame(QNAME_RESULT, result);
        assertEquals(1, compiler.callCount);
        assertEquals("*", compiler.namespace);
        assertEquals("*", compiler.localName);
    }

    @Test
    public void acceptsReservedNameTokensAsNames() throws Exception {
        RecordingCompiler compiler = new RecordingCompiler();
        Object result = parse("and", compiler);

        assertSame(QNAME_RESULT, result);
        assertEquals(1, compiler.callCount);
        assertEquals(null, compiler.namespace);
        assertEquals("and", compiler.localName);
    }

    @Test
    public void acceptsWhitespaceAroundQualifiedName() throws Exception {
        RecordingCompiler compiler = new RecordingCompiler();
        Object result = parse("  prefix : name  ", compiler);

        assertSame(QNAME_RESULT, result);
        assertEquals(1, compiler.callCount);
        assertEquals("prefix", compiler.namespace);
        assertEquals("name", compiler.localName);
    }

    @Test
    public void rejectsEmptyInput() throws Exception {
        assertParseException("");
    }

    @Test
    public void rejectsColonWithoutNamespace() throws Exception {
        assertParseException(":name");
    }

    @Test
    public void rejectsColonWithoutLocalName() throws Exception {
        assertParseException("prefix:");
    }

    @Test
    public void rejectsTwoColons() throws Exception {
        assertParseException("prefix::name");
    }

    @Test
    public void rejectsInvalidCharacter() throws Exception {
        assertParseException("prefix-name");
    }

    private Object parse(String input, RecordingCompiler compiler) throws Exception {
        XPathParser parser = new XPathParser(new StringReader(input));
        setCompiler(parser, compiler.proxy);
        return parser.WildcardName();
    }

    private void assertParseException(String input) throws Exception {
        try {
            parse(input, new RecordingCompiler());
            fail("Expected ParseException for input: " + input);
        } catch (ParseException expected) {
            // Expected.
        }
    }

    private void setCompiler(XPathParser parser, Compiler compiler) throws Exception {
        Class<?> type = parser.getClass();

        while (type != null) {
            Field[] fields = type.getDeclaredFields();

            for (Field field : fields) {
                if (Compiler.class.isAssignableFrom(field.getType())) {
                    field.setAccessible(true);
                    field.set(parser, compiler);
                    return;
                }
            }

            type = type.getSuperclass();
        }

        fail("XPathParser does not contain a Compiler field");
    }

    private static final class RecordingCompiler implements InvocationHandler {
        private final Compiler proxy;
        private int callCount;
        private String namespace;
        private String localName;

        private RecordingCompiler() {
            proxy = (Compiler) Proxy.newProxyInstance(
                    Compiler.class.getClassLoader(),
                    new Class<?>[] {Compiler.class},
                    this);
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) {
            if ("qname".equals(method.getName())) {
                callCount++;
                namespace = (String) args[0];
                localName = (String) args[1];
                return QNAME_RESULT;
            }

            if ("toString".equals(method.getName())) {
                return "RecordingCompiler";
            }

            if ("hashCode".equals(method.getName())) {
                return System.identityHashCode(proxy);
            }

            if ("equals".equals(method.getName())) {
                return proxy == args[0];
            }

            return null;
        }
    }
}

